import java.util.Scanner;

public class CalculadoraScanner {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.print("Primer número: ");
        double a = sc.nextDouble();
        sc.nextLine();

        System.out.print("Segundo número: ");
        double b = sc.nextDouble();
        sc.nextLine();

        System.out.println("\n--- Resultados ---");
        System.out.printf("Suma: %.2f%n", a + b);
        System.out.printf("Resta: %.2f%n", a - b);
        System.out.printf("Multiplicación: %.2f%n", a * b);

        if (b != 0) {
            System.out.printf("División: %.2f%n", a / b);
        } else {
            System.out.println("División: No se puede dividir por cero");
        }

        sc.close();
    }
}

