import java.util.Scanner;

public class FormularioValidado {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Nombre
        String nombre = "";
        while (nombre.isEmpty()) {
            System.out.print("Nombre: ");
            nombre = sc.nextLine().trim();
            if (nombre.isEmpty()) System.out.println("❌ El nombre no puede estar vacío");
        }

        // Edad
        int edad = 0;
        boolean edadValida = false;
        while (!edadValida) {
            System.out.print("Edad: ");
            if (sc.hasNextInt()) {
                edad = sc.nextInt();
                sc.nextLine();
                if (edad > 0 && edad < 150) {
                    edadValida = true;
                } else {
                    System.out.println("❌ La edad debe estar entre 1 y 149");
                }
            } else {
                System.out.println("❌ Debe ser un número entero");
                sc.next();
            }
        }

        // Email
        String email = "";
        while (!email.contains("@")) {
            System.out.print("Email: ");
            email = sc.nextLine().trim();
            if (!email.contains("@")) System.out.println("❌ El email debe contener @");
        }

        // Teléfono
        String telefono = "";
        while (!telefono.matches("\\d{10}")) {
            System.out.print("Teléfono (10 dígitos): ");
            telefono = sc.nextLine().trim();
            if (!telefono.matches("\\d{10}")) System.out.println("❌ Debe tener exactamente 10 dígitos");
        }

        System.out.println("\n=== Registro exitoso ===");
        System.out.println("Nombre: " + nombre);
        System.out.println("Edad: " + edad);
        System.out.println("Email: " + email);
        System.out.println("Teléfono: " + telefono);

        sc.close();
    }
}
